package com.smart.ecommerce.controller;
import com.smart.ecommerce.dto.ApiResponse;import com.smart.ecommerce.dto.user.UserDtos.*;import com.smart.ecommerce.service.UserService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users") @RequiredArgsConstructor public class UserController{private final UserService users; @GetMapping("/me") public ApiResponse<UserResponse> me(Authentication a){return ApiResponse.success("profile",users.me(a.getName()));} @PutMapping("/me") public ApiResponse<UserResponse> update(Authentication a,@Valid @RequestBody UpdateProfileRequest r){return ApiResponse.success("profile updated",users.updateMe(a.getName(),r));} @PutMapping("/me/password") public ApiResponse<Void> password(Authentication a,@Valid @RequestBody ChangePasswordRequest r){users.changePassword(a.getName(),r);return ApiResponse.success("password changed",null);} }
